# Generated by manage.py generate_test_cases.
"""Exercise separate device connections and closed attendance intervals."""

from datetime import timedelta
from typing import Any

from django.core.exceptions import ValidationError

from bloomerp.models.communication.conferencing import ConferenceAttendance
from bloomerp.tests.base import (
    BloomerpModelTestCase,
    ExpectedModelException,
    ModelScenario,
)

from .fixtures import ConferenceFixtures


class TestConferenceAttendanceModel(ConferenceFixtures, BloomerpModelTestCase):
    model = ConferenceAttendance

    def get_test_scenarios(self) -> list[ModelScenario[ConferenceAttendance]]:
        """Cover device identities, timestamp ordering and immutable provider SIDs."""
        return [
            ModelScenario(
                name="Two devices retain separate attendance",
                preparation=self.prepare,
                create_args=self.attendance_args,
                post_create=self.add_device,
            ),
            ModelScenario(
                name="Departure cannot precede arrival",
                preparation=self.prepare,
                create_args=self.invalid_times,
                expected_exceptions=[ExpectedModelException("create", ValidationError)],
            ),
            ModelScenario(
                name="Closed attendance never reopens",
                preparation=self.prepare,
                create_args=self.closed_args,
                update_args={"left_at": None},
                expected_exceptions=[ExpectedModelException("update", ValidationError)],
            ),
            ModelScenario(
                name="Provider SID is immutable once assigned",
                preparation=self.prepare,
                create_args=self.sid_args,
                update_args={"livekit_participant_sid": "PA_other"},
                expected_exceptions=[ExpectedModelException("update", ValidationError)],
            ),
        ]

    def add_device(self, attendance: ConferenceAttendance) -> None:
        """Create another connection for the same participant without overwriting it."""
        other = ConferenceAttendance.objects.create(**self.attendance_args())
        self.assertNotEqual(attendance.livekit_identity, other.livekit_identity)
        self.assertEqual(self.participant.attendances.count(), 2)

    def invalid_times(self) -> dict[str, Any]:
        """Describe a connection whose departure predates arrival."""
        return self.attendance_args(left_at=self.now - timedelta(seconds=1))

    def closed_args(self) -> dict[str, Any]:
        """Describe a closed connection interval."""
        return self.attendance_args(left_at=self.now)

    def sid_args(self) -> dict[str, Any]:
        """Describe attendance with an established provider session identity."""
        return self.attendance_args(livekit_participant_sid="PA_original")
